// Private authoring corpus. Original scenarios; source documents are technical support,
// not company interview questions. Coverage and grade anchors require expert validation.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const authored = [];
function scope(specialization, group, sources) {
  return (slug, title, prompt, criteria, levels, alternatives, errors, language = null) => {
    const parsed = criteria.map(row => row.split('~'));
    authored.push({
      id: `open-${specialization.toLowerCase()}-${slug}`, specialization, group, title, prompt,
      answerFormat: language ? 'code' : 'text', language, sourceIds: sources,
      tags: [slug, specialization.toLowerCase(), group.toLowerCase(), language || 'reasoning'],
      referenceAnswer: parsed.map(([, meets, strong]) => meets + ' ' + strong).join(' '),
      acceptableAlternatives: alternatives, criticalErrors: errors,
      criteria: parsed.map(([label, meets, strong], index) => ({
        id: `${slug}-${index + 1}`, label,
        missing: `Не рассматривает ${label.toLocaleLowerCase('ru')} или предлагает противоположное действие.`,
        partial: `Называет ${label.toLocaleLowerCase('ru')}, но не доводит решение до условия: ${meets}`,
        meets, strong,
      })),
      levels: Object.fromEntries(grades.map((grade, index) => {
        const [task, expected] = levels[index].split('~');
        return [grade, { task, expected }];
      })),
      personalization: { allowed: ['domain', 'entityNames', 'projectContext'], invariants: [
        'Сохранить порядок событий, числовые ограничения, единицы, доверенные стороны и гарантии платформы.',
        'Сохранить механизм задачи, критерии, критические ошибки и дополнительные условия выбранного уровня.',
        'Менять названия и профессиональный контекст без подсказки решения и без оценки богатства опыта.',
      ] },
    });
  };
}

